function LogoFinal(){return <div className="jess-final"><img className="jess-final-art" src="/assets/logo-with-boxes.png" alt="Jess Counselling — interlocking green and gold boxes with a glowing star; Online Counselling Services in Malayalam and English"/></div>}
function Header({active}:{active:PageName}){return <header className="site-header"><a className="brand" href="/"><LogoFinal/></a><nav>{routes.map(([n,h])=><a className={active===n?"active":""} href={h} key={n}>{n[0].toUpperCase()+n.slice(1)}</a>)}</nav>{active!=="appointment"&&(active==="contact"?<span className="button header-button"><span className="consultation-banner-copy">Book a Free <span className="consultation-banner-highlight">Initial Consultation</span></span></span>:<a className="button header-button" href="/contact"><span className="consultation-banner-copy">Book a Free <span className="consultation-banner-highlight">Initial Consultation</span></span></a>)}</header>}
function Footer(){return <footer className="site-footer"><a className="footer-brand" href="/"><LogoFinal/></a><div className="footer-item footer-company"><Building/><span><b>Jess Counselling LLP</b><br/><small>Established as a limited liability entity in India</small></span></div><a className="footer-item" href="mailto:hello@jesscounselling.online"><Mail/><span>hello@jesscounselling.online</span></a><img className="footer-script" src="/assets/footer-script.png" alt="Compassion Creates Change"/><small className="footer-copy">© {new Date().getFullYear()} Jess Counselling LLP. All rights reserved. <a className="footer-disclaimer" href="/disclaimer">Counselling Disclaimer</a></small></footer>}
