function AppointmentDatePicker({value,onChange,appointmentType=""}:{value:string;onChange:(value:string)=>void;appointmentType?:string}){
  const[open,setOpen]=useState(false);
  const[view,setView]=useState(()=>{const d=value?new Date(value+"T00:00:00"):new Date(new Date(Date.now()+19800000).toISOString().slice(0,10)+"T00:00:00");return new Date(d.getFullYear(),d.getMonth(),1)});
  const wrapRef=useRef<HTMLDivElement>(null);
  useEffect(()=>{if(!open)return;const close=(event:PointerEvent)=>{if(wrapRef.current&&!wrapRef.current.contains(event.target as Node))setOpen(false)};document.addEventListener("pointerdown",close);return()=>document.removeEventListener("pointerdown",close)},[open]);
  const display=value?new Intl.DateTimeFormat("en-GB",{day:"numeric",month:"short",year:"numeric"}).format(new Date(value+"T00:00:00")):"Select Date";
  const year=view.getFullYear(),month=view.getMonth(),firstOffset=(new Date(year,month,1).getDay()+6)%7,count=new Date(year,month+1,0).getDate();
  const cells=[...Array(firstOffset).fill(null),...Array.from({length:count},(_,i)=>i+1)];
  const calendar=useBookingCalendar("appointment",year,month,open,appointmentType);
  const iso=(day:number)=>year+"-"+String(month+1).padStart(2,"0")+"-"+String(day).padStart(2,"0");
  return <div className="date-wrap" ref={wrapRef}><button className="date-field" type="button" aria-expanded={open} onClick={()=>setOpen(!open)}><CalendarDays/><span className="date-display">{display}</span></button>{open&&<div className="calendar-popover"><div className="calendar-head"><button type="button" aria-label="Previous month" onClick={()=>setView(new Date(year,month-1,1))}>‹</button><b>{new Intl.DateTimeFormat("en-GB",{month:"long",year:"numeric"}).format(view)}</b><button type="button" aria-label="Next month" onClick={()=>setView(new Date(year,month+1,1))}>›</button></div><div className="calendar-grid">{["Mon","Tue","Wed","Thu","Fri","Sat","Sun"].map(d=><span className="weekday" key={d}>{d}</span>)}{cells.map((day,i)=>day===null?<span className="calendar-empty" key={"e"+i}/>:<button type="button" key={day} className={iso(day)===value?"selected":""} disabled={!calendar.available(iso(day))} onClick={event=>{if(window.matchMedia("(max-width: 600px)").matches){event.preventDefault();event.stopPropagation()}onChange(iso(day));setOpen(false)}}>{day}</button>)}</div>{calendar.message&&<small role="status" className={isBookingIssue(calendar.message)?"booking-message-error":calendar.message==="Checking available dates…"?"calendar-availability-pending":undefined}>{calendar.message}</small>}</div>}</div>
}



